// Gaussian camera conventions: right/up/back form an orthonormal world basis.
// Inria cameras.json stores camera-to-world columns right/down/forward.
const gsDot3 = (a, b) => a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
