  grayscale: {label: t('灰度'), stops: [[.08,.08,.08],[.95,.95,.95]]},
  'blue-white-red': {label: t('蓝—白—红'), stops: [[.17,.35,.75],[.97,.97,.97],[.78,.16,.20]]},
